from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def is_valid(key, t):
        if key not in cache:
            return False
        value, wtime = cache[key]
        return t < wtime + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache and is_valid(key, t):
                # update existing entry, refresh time and move to most recently used
                cache.move_to_end(key)
                cache[key] = [value, t]
            else:
                # remove stale/expired entry if present
                if key in cache:
                    del cache[key]

                # count currently valid entries
                valid_count = 0
                for k, (v, wt) in cache.items():
                    if t < wt + ttl:
                        valid_count += 1

                if valid_count >= capacity:
                    # evict least recently used valid entry
                    for k in list(cache.keys()):
                        v, wt = cache[k]
                        if t < wt + ttl:
                            del cache[k]
                            break

                cache[key] = [value, t]
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache and is_valid(key, t):
                results.append(cache[key][0])
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

